// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 seedDrugs) public {
        // Bound seedDrugs to avoid overflow in marketDrugs
        vm.assume(seedDrugs > 0 && seedDrugs < 1e18);
        // Initialize the contract with seedDrugs
        c.seedMarket(seedDrugs);
        // Ensure caller is not the zero address and has zero kilos before getFreeKilo
        vm.assume(caller != address(0));
        // Call getFreeKilo as the first-time caller
        vm.prank(caller);
        c.getFreeKilo();
        // Now call DrugDealer (which we assume may affect state)
        vm.prank(c.ceoAddress());
        c.DrugDealer();
        // The rule: after DrugDealer, the caller's Kilos must be at least 1 (since in reference it is STARTING_KILOS=300, but even in bug it is 0)
        assertTrue(c.Kilos(caller) >= 1);
    }
}

